func (b *APIBuilder) UpdateAPIGroupInfo(apiGroupInfo *genericapiserver.APIGroupInfo, opts builder.APIGroupOptions) error {
	storage := map[string]rest.Storage{}

	// Configure Stars Dual writer
	resource := collections.StarsResourceInfo
	var stars grafanarest.Storage
	stars, err := grafanaregistry.NewRegistryStore(opts.Scheme, resource, opts.OptsGetter)
	if err != nil {
		return err
	}
	if b.legacyStars != nil && opts.DualWriteBuilder != nil {
		stars, err = opts.DualWriteBuilder(resource.GroupResource(), b.legacyStars, stars)
		if err != nil {
			return err
		}
	}
	storage[resource.StoragePath()] = &starStorage{Storage: stars} // wrap List so we only return one value
	storage[resource.StoragePath("update")] = &starsREST{store: stars}

	apiGroupInfo.VersionedResourcesStorageMap[collections.APIVersion] = storage
	return nil

s-update.text:
// NOTE: the authorizer has already verified that the user is allowed to modify this resource
func (r *starsREST) Connect(ctx context.Context, name string, _ runtime.Object, responder rest.Responder) (http.Handler, error) {
	namespace, ok := request.NamespaceFrom(ctx)
	if !ok {
		return nil, fmt.Errorf("stars must belong to a namespace")
	}
	parsed, found := utils.ParseOwnerFromName(name)
	if !found || parsed.Owner != utils.UserResourceOwner {
		return nil, fmt.Errorf("only works with user stars")
	}

	return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		item, err := itemFromPath(req.URL.Path, fmt.Sprintf("/%s/update", name))
		if err != nil {
			responder.Error(err)
			return
		}

		remove := false
		switch req.Method {
		case "DELETE":
			remove = true
		case "PUT":
			remove = false
		default:
			responder.Error(apierrors.NewMethodNotSupported(collections.StarsResourceInfo.GroupResource(), req.Method))
			return
		}

		current, err := r.store.Get(ctx, name, &v1.GetOptions{})
		if err != nil {
			if apierrors.IsNotFound(err) {
				if remove {
					responder.Object(http.StatusNoContent, &v1.Status{
						Code: http.StatusNoContent,
					})
					return
				}
				current = &collections.Stars{
					ObjectMeta: v1.ObjectMeta{
						Name:      name,
						Namespace: namespace,
					},
				}
			}
		}

		obj, ok := current.(*collections.Stars)
		if !ok {
			responder.Error(fmt.Errorf("expected stars object"))
			return
		}

		if remove {
			obj.Spec.Remove(item.group, item.kind, item.id)
		} else {
			obj.Spec.Add(item.group, item.kind, item.id)
		}

		if len(obj.Spec.Resource) == 0 {
			_, _, err = r.store.Delete(ctx, name, rest.ValidateAllObjectFunc, &v1.DeleteOptions{})
		} else if obj.ResourceVersion == "" {
			_, err = r.store.Create(ctx, obj, rest.ValidateAllObjectFunc, &v1.CreateOptions{})
		} else {
			_, _, err = r.store.Update(ctx, name, rest.DefaultUpdatedObjectInfo(obj), rest.ValidateAllObjectFunc, rest.ValidateAllObjectUpdateFunc, true, &v1.UpdateOptions{})
		}
		if err != nil {
			responder.Error(err)
			return
		}
		responder.Object(http.StatusOK, &v1.Status{Code: http.StatusOK})
	}), nil

s-spec.text:
func (stars *StarsSpec) Add(group, kind, name string) {
	for i, r := range stars.Resource {
		if r.Group == group && r.Kind == kind {
			stars.Resource[i].Names = append(r.Names, name)
			stars.Normalize()
			return
		}
	}

	// Add the resource kind
	stars.Resource = append(stars.Resource, StarsResource{
		Group: group,
		Kind:  kind,
		Names: []string{name},
	})
	stars.Normalize()
}

func (stars *StarsSpec) Remove(group, kind, name string) {
	for i, r := range stars.Resource {
		if r.Group == group && r.Kind == kind {
			idx := slices.Index(r.Names, name)
			if idx < 0 {
				return // does not exist
			}
			r.Names = append(r.Names[:idx], r.Names[idx+1:]...)
			stars.Resource[i].Names = r.Names
			if len(r.Names) == 0 {
				stars.Normalize()
			}
			return
		}
	}
}

// Makes sure everything is in sorted order
func (stars *StarsSpec) Normalize() {
	resources := make([]StarsResource, 0, len(stars.Resource))
	for _, r := range stars.Resource {
		if len(r.Names) > 0 {
			unique := make([]string, 0, len(r.Names))
			found := make(map[string]bool, len(r.Names))
			for _, name := range r.Names {
				if !found[name] {
					unique = append(unique, name)
					found[name] = true
				}
			}
			r.Names = unique
			resources = append(resources, r)
		}
	}
	slices.SortFunc(resources, func(a StarsResource, b StarsResource) int {
		return strings.Compare(a.Group+a.Kind, b.Group+b.Kind)
	})
	if len(resources) == 0 {
		resources = nil
	}
	stars.Resource = resources
}

