    getDashboardUrl({
      uid: v.metadata.name,
      currentQueryParams: '',
      slug,
    })
  );

  return {
    uid: v.metadata.name,
    version: v.metadata.generation ?? 0,
    status: 'success',
    url,
    slug,
  };

